// Match customer text against deterministic FAQ keywords
const text = items[0].json.incoming_text.toLowerCase();
const faqs = items[0].json.faqs || [];

let matchedAnswer = null;
for (const faq of faqs) {
  const keywords = Array.isArray(faq.keywords) ? faq.keywords : JSON.parse(faq.keywords || '[]');
  for (const kw of keywords) {
    if (text.includes(kw.toLowerCase())) {
      matchedAnswer = faq.answer;
      break;
    }
  }
  if (matchedAnswer) break;
}

return [{
  json: {
    found: !!matchedAnswer,
    answer: matchedAnswer || 'Thank you for reaching Kedar Enterprises. Type 1 for Products, 2 for Pricing, 3 for Enquiry, 4 for Business Info, or 5 to Talk to Staff.'
  }
}];
